'@

function Test-Verified([string]$Path, [string]$Sha256, [long]$Size) {
  if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $false }
  if ((Get-Item -LiteralPath $Path).Length -ne $Size) { return $false }
  return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash -eq $Sha256
}

# Downloads $Url into $Partial, resuming from its current length when the
# server honours Range (206); otherwise restarts from byte 0.
function Receive-File([string]$Url, [string]$Partial, [long]$Size) {
  $offset = 0L
  if (Test-Path -LiteralPath $Partial) {
    $offset = (Get-Item -LiteralPath $Partial).Length
    if ($offset -ge $Size) { Remove-Item -LiteralPath $Partial; $offset = 0L }
  }
  $request = [Net.HttpWebRequest]::Create($Url)
  $request.Timeout = 60000
  $request.ReadWriteTimeout = 60000
  if ($offset -gt 0) { $request.AddRange($offset) }
  $response = $request.GetResponse()
  try {
    $mode = [IO.FileMode]::Create
    if ($offset -gt 0 -and [int]$response.StatusCode -eq 206) { $mode = [IO.FileMode]::Append }
    $in = $response.GetResponseStream()
    $out = [IO.File]::Open($Partial, $mode, [IO.FileAccess]::Write)
    try { $in.CopyTo($out, 1MB) } finally { $out.Dispose(); $in.Dispose() }
  } finally {
    $response.Dispose()
  }
}

$entries = @($Manifest -split "`n" | Where-Object { $_.Trim() } | ForEach-Object {
  $f = $_.TrimEnd("`r").Split("`t")
  [pscustomobject]@{ Path = $f[0]; Sha256 = $f[1]; Size = [long]$f[2] }
})
if ($entries.Count -ne $ExpectedCount) { throw "manifest has $($entries.Count) entries, expected $ExpectedCount" }

$root = [IO.Path]::GetFullPath($Destination)
New-Item -ItemType Directory -Force -Path $root | Out-Null
Write-Host "fetch_bistro: $($entries.Count) files -> $root"

$clock = [Diagnostics.Stopwatch]::StartNew()
$skipped = 0; $downloaded = 0; $downloadedBytes = 0L; $failed = @()
$index = 0
foreach ($e in $entries) {
  $index++
  $target = Join-Path $root ($e.Path -replace '/', '\')
  if (Test-Verified $target $e.Sha256 $e.Size) { $skipped++; continue }
  New-Item -ItemType Directory -Force -Path (Split-Path -Parent $target) | Out-Null
  $partial = "$target.partial"
  $url = $BaseUrl + (($e.Path -split '/' | ForEach-Object { [Uri]::EscapeDataString($_) }) -join '/')
  $ok = $false
  for ($attempt = 1; $attempt -le $MaxRetries -and -not $ok; $attempt++) {
    try {
      Receive-File $url $partial $e.Size
      if (Test-Verified $partial $e.Sha256 $e.Size) {
        Move-Item -LiteralPath $partial -Destination $target -Force
        $ok = $true
      } elseif ((Get-Item -LiteralPath $partial).Length -ge $e.Size) {
        Write-Warning "[$index] $($e.Path): size/SHA256 mismatch (attempt $attempt), discarding"
        Remove-Item -LiteralPath $partial
      }
    } catch {
      Write-Warning "[$index] $($e.Path): $($_.Exception.Message) (attempt $attempt)"
    }
    if (-not $ok -and $attempt -lt $MaxRetries) { Start-Sleep -Seconds ([Math]::Min(30, 2 * $attempt)) }
  }
  if ($ok) {
    $downloaded++; $downloadedBytes += $e.Size
    Write-Host ("[{0}/{1}] {2} ({3:N1} MB)" -f $index, $entries.Count, $e.Path, ($e.Size / 1MB))
  } else {
    $failed += $e.Path
  }
}
$clock.Stop()

$totalBytes = ($entries | Measure-Object -Property Size -Sum).Sum
Write-Host ("fetch_bistro: {0} downloaded ({1:N0} bytes), {2} already verified, {3} failed; {4:N0} bytes total; {5:N1} s" -f `
  $downloaded, $downloadedBytes, $skipped, $failed.Count, $totalBytes, $clock.Elapsed.TotalSeconds)
if ($failed.Count -gt 0) {
  $failed | ForEach-Object { Write-Host "FAILED: $_" }
  exit 1
}
Write-Host "fetch_bistro: all $($entries.Count) files verified (SHA256 = pinned LFS oid)."
exit 0
